#!/usr/bin/env python3
"""Compute the denominator/scale audit ground truth for CSX-004 Q2."""

from __future__ import annotations

import csv
import json
import re
from collections import Counter
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-004_Q2"
EVENT_ID = "CSX-004"
ANSWER_TYPE = "denominator_scale_audit"
ASSET_CATEGORIES = ("hospital", "school", "police", "shelter", "fire_station")


def package_root() -> Path:
    here = Path(__file__).resolve()
    for parent in here.parents:
        candidate = parent / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
        if candidate.is_dir():
            return candidate
    raise FileNotFoundError(f"Could not locate package {EVENT_ID}")


def read_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_manifest(root: Path) -> list[dict[str, str]]:
    with (root / "metadata" / "files.csv").open("r", encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def select_one(
    rows: list[dict[str, str]],
    *,
    data_category: str | None = None,
    layer_name: str | None = None,
    source_contains: str | None = None,
    relative_path: str | None = None,
) -> str:
    accepted_statuses = {"success", "downloaded", "remote_verified", "local_file_found"}
    candidates: list[dict[str, str]] = []
    for row in rows:
        if row.get("file_status") not in accepted_statuses:
            continue
        if relative_path and row.get("relative_path") != relative_path:
            continue
        if data_category and row.get("data_category") != data_category:
            continue
        if layer_name and row.get("layer_name") != layer_name:
            continue
        if source_contains and source_contains.lower() not in row.get("source_name", "").lower():
            continue
        candidates.append(row)
    if not candidates:
        raise FileNotFoundError(
            f"No manifest row matched category={data_category} layer={layer_name} "
            f"source={source_contains} path={relative_path}"
        )
    return candidates[0]["relative_path"]


def inclusive_days(start_date: str, end_date: str) -> int:
    start = date.fromisoformat(start_date)
    end = date.fromisoformat(end_date)
    return (end - start).days + 1


def amenity_counts(osm: dict[str, Any]) -> Counter[str]:
    counts: Counter[str] = Counter()
    for element in osm.get("elements", []):
        tags = element.get("tags") or {}
        amenity = tags.get("amenity")
        if amenity in ASSET_CATEGORIES:
            counts[amenity] += 1
    return counts


def extract_people_count(text: str) -> int:
    match = re.search(r"(?:at least|about)?\s*([0-9][0-9,]*)\s+people", text, flags=re.I)
    if not match:
        raise ValueError("Could not extract reported people count")
    return int(match.group(1).replace(",", ""))


def build_gt() -> dict[str, Any]:
    root = package_root()
    rows = read_manifest(root)

    event_anchor_rel = select_one(
        rows,
        relative_path="data/event_reports/event_reports_005_Locked_event_anchor_2015_India-Pakistan_heat_wave.json",
    )
    regional_heat_rel = select_one(rows, data_category="physical_hazard", layer_name="era5_land")
    population_rel = select_one(rows, data_category="exposure_impact", layer_name="worldpop_population")
    asset_rel = select_one(
        rows,
        relative_path="data/exposure_impact/exposure_impact_006_OpenStreetMap_Overpass_bounded_AOI_slice.json",
    )
    small_overpass_rel = select_one(
        rows,
        relative_path="data/exposure_impact/exposure_impact_003_Overpass_small_roads_and_critical_amenities.json",
    )
    india_report_rel = select_one(
        rows,
        data_category="event_reports",
        layer_name="event_anchor_report",
        source_contains="Indian heat wave",
    )
    pakistan_report_rel = select_one(
        rows,
        data_category="event_reports",
        layer_name="event_anchor_report",
        source_contains="Pakistan heat wave",
    )

    event_anchor = read_json(root / event_anchor_rel)
    regional_heat = read_json(root / regional_heat_rel)
    population = read_json(root / population_rel)
    selected_osm = read_json(root / asset_rel)
    small_osm = read_json(root / small_overpass_rel)
    india_report = read_json(root / india_report_rel)
    pakistan_report = read_json(root / pakistan_report_rel)

    start_date = event_anchor["temporal_window"]["start_date"]
    end_date = event_anchor["temporal_window"]["end_date"]
    stats = regional_heat["stats"]

    population_raw = float(population["population_sum"]["population"])
    population_m = population_raw / 1_000_000.0

    selected_counts = amenity_counts(selected_osm)
    small_counts = amenity_counts(small_osm)
    heat_health_assets = sum(selected_counts[category] for category in ASSET_CATEGORIES)
    small_assets = sum(small_counts[category] for category in ASSET_CATEGORIES)

    india_deaths = extract_people_count(india_report.get("extract", ""))
    pakistan_deaths = extract_people_count(pakistan_report.get("extract", ""))

    primary_gt = {
        "answer_type": ANSWER_TYPE,
        "decision": "population_denominator_required_for_service_exposure_rate",
        "source_paths": {
            "event_anchor": event_anchor_rel,
            "regional_heat": regional_heat_rel,
            "population_denominator": population_rel,
            "asset_numerator": asset_rel,
            "smaller_overpass_candidate": small_overpass_rel,
            "india_report_context": india_report_rel,
            "pakistan_report_context": pakistan_report_rel,
            "manifest": "metadata/files.csv",
        },
        "event_window": {
            "start_date": start_date,
            "end_date": end_date,
            "days_inclusive": inclusive_days(start_date, end_date),
        },
        "regional_heat_context": {
            "dataset": regional_heat["dataset"],
            "temperature_2m_max_c_max": round(float(stats["temperature_2m_max_c_max"]), 2),
            "temperature_2m_max_c_mean": round(float(stats["temperature_2m_max_c_mean"]), 2),
            "temperature_2m_max_c_min": round(float(stats["temperature_2m_max_c_min"]), 2),
        },
        "selected_exposure_inputs": {
            "population": round(population_raw, 2),
            "population_m": round(population_m, 2),
            "asset_category_counts": {category: selected_counts[category] for category in ASSET_CATEGORIES},
            "heat_health_assets": heat_health_assets,
            "selected_osm_elements": len(selected_osm.get("elements", [])),
        },
        "calculations": {
            "assets_per_million_people": round(heat_health_assets / population_m, 2),
            "residents_per_heat_health_asset": round(population_raw / heat_health_assets, 2),
        },
        "counterfactual_audit": {
            "osm_elements_as_denominator": {
                "wrong_denominator": len(selected_osm.get("elements", [])),
                "wrong_fraction": round(heat_health_assets / len(selected_osm.get("elements", [])), 3),
                "error_class": "wrong_denominator_mixed_osm_feature_inventory",
            },
            "smaller_overpass_as_numerator": {
                "wrong_assets": small_assets,
                "wrong_assets_per_million_people": round(small_assets / population_m, 2),
                "undercount_assets": heat_health_assets - small_assets,
                "selected_to_wrong_asset_ratio": round(heat_health_assets / small_assets, 2),
                "error_class": "wrong_numerator_incomplete_overpass_slice",
            },
            "reported_deaths_as_denominator": {
                "india_deaths": india_deaths,
                "pakistan_deaths": pakistan_deaths,
                "combined_reported_deaths": india_deaths + pakistan_deaths,
                "why_rejected": "reported deaths are impact context, not exposed population or service inventory",
            },
        },
        "minimal_evidence_set": [
            event_anchor_rel,
            regional_heat_rel,
            population_rel,
            asset_rel,
            small_overpass_rel,
            india_report_rel,
            pakistan_report_rel,
            "metadata/files.csv",
        ],
        "ruling": "population_scaled_exposure_density_supported",
        "reference_trace": [
            "Use metadata/files.csv to identify locked event anchor, ERA5-Land stats, WorldPop sum, bounded OSM slice, smaller Overpass candidate, and report contexts.",
            "Read the locked anchor temporal_window and compute inclusive days from 2015-05-01 through 2015-06-30.",
            "Read ERA5-Land temperature_2m_max_c_* fields as regional heat context only.",
            "Read WorldPop population_sum.population and convert to millions.",
            "Count only hospital, school, police, shelter, and fire_station amenities in the bounded OSM AOI slice.",
            "Compute assets per million people and residents per heat-health asset.",
            "Reject OSM element count, the smaller Overpass slice, and reported deaths as denominator or numerator shortcuts.",
        ],
    }
    compact_primary_gt = {
        "answer": primary_gt["decision"],
        "answer_type": ANSWER_TYPE,
        "decision": primary_gt["decision"],
        "key_values": {
            "days_inclusive": primary_gt["event_window"]["days_inclusive"],
            "population": primary_gt["selected_exposure_inputs"]["population"],
            "heat_health_assets": heat_health_assets,
            "assets_per_million_people": primary_gt["calculations"]["assets_per_million_people"],
            "residents_per_heat_health_asset": primary_gt["calculations"]["residents_per_heat_health_asset"],
        },
        "rejected_shortcuts": [
            "osm_elements_as_denominator",
            "smaller_overpass_as_numerator",
            "reported_deaths_as_denominator",
        ],
        "source_paths": {
            "population_denominator": population_rel,
            "asset_numerator": asset_rel,
        },
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "answer_type": ANSWER_TYPE,
        "task_type": "short_answer",
        "target_family": "heat_health_exposure_denominator_audit",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": compact_primary_gt,
        "answer_detail": {
            "expected_answer": primary_gt,
        },
        "numeric_tolerances": {
            "temperature_c": 0.01,
            "population": 0.01,
            "population_m": 0.01,
            "assets_per_million_people": 0.01,
            "residents_per_heat_health_asset": 0.01,
            "wrong_fraction": 0.001,
            "selected_to_wrong_asset_ratio": 0.01,
        },
        "scoring_notes": {
            "path_policy": "All source paths in primary_gt are package-relative.",
            "external_sources": "No web or hidden-answer evidence is required or allowed.",
            "critical_error": "Using OSM feature count or reported deaths as the population denominator should be scored as a denominator/scale failure.",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "requested_json_schema",
                    "points": 3,
                    "description": "Returns the requested JSON schema with package-relative paths and no external evidence.",
                    "partial_credit": "Award up to 2 points for a mostly correct object with minor field-name or ordering issues.",
                },
                {
                    "name": "event_window_and_heat_context",
                    "points": 3,
                    "description": "Uses the locked event window and ERA5-Land heat-context fields correctly.",
                    "partial_credit": "Award up to 2 points if the heat values are correct but the event window or context-only role is incomplete.",
                },
                {
                    "name": "population_denominator",
                    "points": 3,
                    "description": "Uses the WorldPop population denominator and converts it to millions correctly.",
                    "partial_credit": "Award up to 2 points for the correct source with a rounding or conversion error.",
                },
                {
                    "name": "bounded_osm_numerator",
                    "points": 4,
                    "description": "Counts the bounded OSM heat-health service assets by the requested amenity categories.",
                    "partial_credit": "Award up to 3 points for the right file and total but one category error; up to 2 points for using the right categories on the wrong OSM slice.",
                },
                {
                    "name": "rate_calculations",
                    "points": 3,
                    "description": "Computes assets per million people and residents per heat-health asset with correct rounding.",
                    "partial_credit": "Award up to 2 points for correct formulas with one arithmetic or rounding error.",
                },
                {
                    "name": "counterfactual_rejections",
                    "points": 3,
                    "description": "Rejects OSM element count, the smaller Overpass numerator, and reported deaths as denominator or numerator shortcuts.",
                    "partial_credit": "Award 1 point for each correctly rejected shortcut with a source-specific reason.",
                },
                {
                    "name": "final_ruling_and_trace",
                    "points": 1,
                    "description": "Gives the correct final ruling and a reproducible trace without generic disaster explanation.",
                    "partial_credit": "Award this point only when the final ruling follows from the computed denominator-scale audit.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": primary_gt["minimal_evidence_set"],
        },
    }


def main() -> None:
    out_path = Path(__file__).resolve().parent / "computed_gt.json"
    out_path.write_text(json.dumps(build_gt(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
